import yaml,re
src=open('claude-dev-log-diary/day-004.md').read()
norm=' '.join(src.split())
d=yaml.safe_load(open('.coordination/mining/v2/day-004.yaml'))
bad=[]
def chk(q,where):
    qn=' '.join(q.split())
    if qn not in norm: bad.append((where,qn[:90]))
for p in d['philosophy']:
    if p.get('quote'): chk(p['quote'],'phil '+p['loc'])
for r in d['skill_rules']:
    if r.get('quote'): chk(r['quote'],'rule '+r['rule_id'])
for f in d['failure_modes']:
    chk(f['quote'],'fail '+f['name']+' '+f['loc'])
for p in d['pairing_rules']:
    if p.get('quote'): chk(p['quote'],'pair '+p['rule_id'])
print('MISMATCHES:',len(bad))
for b in bad: print(b)
